              const oldNum = Number(String(duplicateInfo.existingRow.values[qtyCol.header] ?? '0').match(/-?\d+(?:\.\d+)?/)?.[0] ?? 0);
              const addNum = Number(String(rawData[qtyCol.header] ?? '0').match(/-?\d+(?:\.\d+)?/)?.[0] ?? 0);
