  clearPromptInjection(null);
  const targets = [globalThis, getHostWindow()].filter(Boolean);
  for (const target of targets) {
    try {
      delete target[INTERCEPTOR_GLOBAL_NAME];
    } catch {
      target[INTERCEPTOR_GLOBAL_NAME] = undefined;
    }
  }
}

