exports.INTERCEPTOR_GLOBAL_NAME = INTERCEPTOR_GLOBAL_NAME;
exports.clearPromptInjection = clearPromptInjection;
exports.applyChatPromptInjection = applyChatPromptInjection;
exports.getActiveInjectionStatus = getActiveInjectionStatus;
exports.getChannelDisplayName = getChannelDisplayName;
exports.registerGenerateInterceptor = registerGenerateInterceptor;
exports.unregisterGenerateInterceptor = unregisterGenerateInterceptor;
